        spkey = [k for k in b if _h_norm(k) == _h_norm('Danh sách hàng hóa')][0]
        sp = b[spkey].copy()
        ct['dt'] = _h_dates(ct['Ngày'])
        st = ct['Trạng thái'].astype(str).str.strip()
        ct['st_norm'] = np.select([st.str.contains('huỷ|hủy|cancel', case=False, na=False), st.str.contains('trả|return', case=False, na=False)], ['cancel', 'return'], default='ok')
        ct['ttien'] = _h_mnum(ct['Thành tiền'])
        ct['gia'] = _h_mnum(ct['Đơn giá'])
        ct['slqd'] = pd.to_numeric(ct['Số lượng quy đổi'], errors='coerce')
        sp['name_n'] = sp['Tên hàng hóa'].map(_h_norm)
        sp['size'] = sp['Tên hàng hóa'].str.extract('\\(([ML])\\)$', flags=re.I)[0].str.upper()
        sp['group_n'] = sp['Nhóm hàng hóa'].map(_h_norm)
        m = sp.drop_duplicates('name_n').set_index('name_n')
        ct['name_n'] = ct['Tên hàng hóa'].map(_h_norm)
        ct['sku'] = ct['name_n'].map(m['Mã hàng hóa'])
        ct['canon'] = ct['name_n'].map(m['Tên hàng hóa'])
        ct['size'] = ct['name_n'].map(m['size'])
        ct['group_n'] = ct['name_n'].map(m['group_n'])
        _h__b = dict(ct=ct, sp=sp)
    return _h__b

def _h_product_qty(ct, y, m, name):
    sub = ct[(ct['st_norm'] == 'ok') & _h_month_mask(ct['dt'], y, m)]
    return float(sub.loc[sub['name_n'] == _h_norm(name), 'slqd'].sum())

def _h_group_rev(ct, y, m, group):
    sub = ct[(ct['st_norm'] == 'ok') & _h_month_mask(ct['dt'], y, m)]
    return float(sub.loc[sub['group_n'] == _h_norm(group), 'ttien'].sum())

def _h_month_mask(dt, y, m):
    s = pd.Timestamp(year=y, month=m, day=1)
    e = s + pd.offsets.MonthBegin(1)
    return (dt >= s) & (dt < e)

